{
  "lemmas": [
    {
      "lemma": "property lemma_1; @(posedge clk) disable iff (rst) (i <= N); endproperty",
      "explanation": "Bounds the loop index. When N fits in i, the index can advance only as far as N; this rules out an arbitrary larger index when LOOP transitions to DONE."
    },
    {
      "lemma": "property lemma_2; @(posedge clk) disable iff (rst) ((N > $unsigned({WIDTH{1'b1}})) || (sum == i / 8)); endproperty",
      "explanation": "For a representable N, each multiple of eight reached by i increments sum, giving sum == i / 8. The guard is necessary for parameterizations where i wraps before reaching N."
    },
    {
      "lemma": "property lemma_3; @(posedge clk) disable iff (rst) ((state != DONE) || (i == N)); endproperty",
      "explanation": "The FSM enters DONE only after the bounded index reaches N. Together with lemma_2 and N == 8*n, this yields sum == n in DONE."
    }
  ]
}
</json>
